xs = sp.symbols("x0:10")
ones = [tuple(row) for row, y in zip(spec["inputs"], spec["outputs"]) if y]
expr = sp.SOPform(xs, ones)

# Compile the minimized expression into threshold gates, one Boolean signal per
# triple. Each layer has room for eight signals.
ops = []
def put(tensor, index, value):
    if value:
        ops.append({"op": "set", "tensor": tensor, "index": index, "value": float(value)})

# Preserve the ten raw inputs through all four ReLU layers.
for i in range(10):
    put("w0", [i, i], 1)
    for layer in range(1, 4):
        put(f"w{layer}", [i, i], 1)

def children(node):
    if node.func in (sp.And, sp.Or):
        return list(node.args)
    if node.func is sp.Not:
        return [node.args[0]]
    return []

stage_cache = {}
def stage(node):
    if node in stage_cache:
        return stage_cache[node]
    if node in xs or node in (sp.true, sp.false):
        return -1
    s = 1 + max((stage(c) for c in children(node)), default=-1)
    stage_cache[node] = s
    return s

def literal_terms(node):
    # Return (linear coefficients, constant, threshold) for a single
    # threshold gate implementing an And/Or of literals.
    args = list(node.args)
    is_and = node.func is sp.And
    coeff, const = {}, 0
    for a in args:
        neg = a.func is sp.Not
        v = a.args[0] if neg else a
        if v not in xs and v not in stage_cache:
            stage(v)
        if v in xs:
            idx = xs.index(v)
            ref = ("input", idx)
        else:
            ref = ("gate", v)
        coeff[ref] = coeff.get(ref, 0) + (-1 if neg else 1)
        if neg:
            const += 1
    threshold = len(args) if is_and else 1
    return coeff, const, threshold

def emit(node):
    if node in xs or node in (sp.true, sp.false):
        return
    if node in emitted:
        return
    for c in children(node):
        emit(c)
    s = stage(node)
    if s < 0 or s > 3:
        raise ValueError("Minimized expression exceeds four network stages")
    slot = slots[s]
    if slot >= 8:
        raise ValueError("Minimized expression exceeds eight signals in a stage")
    slots[s] += 1
    base = 10 + 3 * slot
    emitted[node] = (s, base)

    if node is sp.true or node is sp.false:
        coeff, const, threshold = {}, int(node is sp.true), 1
    elif node.func is sp.Not:
        v = node.args[0]
        coeff, const, threshold = {}, 1, 1
        ref = ("input", xs.index(v)) if v in xs else ("gate", v)
        coeff[ref] = -1
    else:
        coeff, const, threshold = literal_terms(node)

    wname, bname = f"w{s}", f"b{s}"
    for ref, c in coeff.items():
        if ref[0] == "input":
            src = ref[1]
            put(wname, [base, src], c)
            put(wname, [base + 2, src], -c)
        else:
            ps, pb = emitted[ref[1]]
            if ps != s - 1:
                raise ValueError("Gate schedule is not stage-compatible")
            put(wname, [base, pb], c)
            put(wname, [base, pb + 2], -c)
            put(wname, [base + 2, pb], -c)
            put(wname, [base + 2, pb + 2], c)

    put(bname, base, const - threshold + 1)
    put(bname, base + 2, const - threshold)

emitted, slots = {}, [0, 0, 0, 0]
emit(expr)
if expr is sp.true:
