nodes = set()
def collect(n):
    if n in xs or n in (sp.true, sp.false) or n in nodes:
        return
    nodes.add(n)
    for c in children(n):
        collect(c)
collect(expr)

def depth(n, memo={}):
    if n in xs or n in (sp.true, sp.false):
        return -1
    if n not in memo:
        memo[n] = 1 + max((depth(c) for c in children(n)), default=-1)
    return memo[n]

ordered = sorted(nodes, key=lambda n: (depth(n), str(n)))
consumers = {n: [] for n in nodes}
for n in nodes:
    for c in children(n):
        if c in nodes:
            consumers[c].append(n)

def live_counts(assign):
    counts = []
    for layer in range(4):
        live = [
            n for n in nodes
            if assign[n] <= layer and
            (n == expr or any(assign[p] > layer for p in consumers[n]))
        ]
        counts.append(len(live))
    return counts

# Schedule gates with no more than eight simultaneously live Boolean signals.
assignment = {}
def schedule(i=0):
    if i == len(ordered):
        return max(live_counts(assignment)) <= 8
    n = ordered[i]
    deps = [c for c in children(n) if c in nodes]
    earliest = max((assignment[c] + 1 for c in deps), default=0)
    for layer in range(earliest, 4):
        assignment[n] = layer
        if max(live_counts(assignment)) <= 8 and schedule(i + 1):
            return True
    assignment.pop(n, None)
    return False

