        key=str
    )
    if len(live[layer]) > 8:
        raise ValueError("More than eight live signals in a layer")
    slot[layer] = {n: 10 + 3 * k for k, n in enumerate(live[layer])}

def ref(n, layer):
    if n in xs:
        return ("input", xs.index(n))
    return ("signal", slot[layer][n])

for layer in range(4):
    # Copy live signals forward using their two nonnegative rails.
    if layer:
        for n in live[layer]:
            if assignment[n] < layer:
                src, dst = slot[layer - 1][n], slot[layer][n]
                put(f"w{layer}", [dst, src], 1)
                put(f"w{layer}", [dst + 2, src + 2], 1)

    for n in ordered:
        if assignment[n] != layer:
            continue
        dst = slot[layer][n]
        if n.func is sp.Not:
            args, is_and, const, threshold = [n.args[0]], True, 1, 1
            literals = [(args[0], -1)]
        else:
            args = list(n.args)
            is_and = n.func is sp.And
            const, literals = 0, []
            for a in args:
                neg = a.func is sp.Not
                v = a.args[0] if neg else a
                literals.append((v, -1 if neg else 1))
                if neg:
                    const += 1
            threshold = len(args) if is_and else 1

        for v, coef in literals:
            kind, ix = ref(v, layer - 1) if layer else (
                ("input", xs.index(v)) if v in xs else ("signal", None)
            )
            if kind == "input":
                put(f"w{layer}", [dst, ix], coef)
                put(f"w{layer}", [dst + 2, ix], coef)
            else:
                src = slot[layer - 1][v]
                put(f"w{layer}", [dst, src], coef)
                put(f"w{layer}", [dst, src + 2], -coef)
                put(f"w{layer}", [dst + 2, src], coef)
                put(f"w{layer}", [dst + 2, src + 2], -coef)

        put(f"b{layer}", [dst], const - threshold + 1)
        put(f"b{layer}", [dst + 2], const - threshold)

# Encode the Boolean result in logits; class 0 wins when the result is false.
if expr is sp.true:
    put("bias", [1], 1)
elif expr is sp.false:
    put("bias", [1], -1)
elif expr in xs:
    put("out", [1, xs.index(expr)], 1)
else:
    src = slot[3][expr]
    put("out", [1, src], 1)
    put("out", [1, src + 2], -1)
put("bias", [2], -1)

