import json
import sympy as sp

spec = TASK["public"]["specification"]
xs = sp.symbols("x0:10")
ones = [tuple(row) for row, y in zip(spec["inputs"], spec["outputs"]) if y]
expr = sp.SOPform(xs, ones)

def is_input_literal(n):
    return n in xs or (n.func is sp.Not and n.args[0] in xs)

def children(n):
    if n.func in (sp.And, sp.Or):
        return [c for c in n.args if not is_input_literal(c)]
    if n.func is sp.Not and not is_input_literal(n):
        return [n.args[0]]
    return []

nodes = set()
def collect(n):
    if n in xs or n in (sp.true, sp.false) or is_input_literal(n) or n in nodes:
        return
    nodes.add(n)
    for c in children(n):
        collect(c)
collect(expr)

def depth(n, memo={}):
    if n in xs or n in (sp.true, sp.false) or is_input_literal(n):
        return -1
    if n not in memo:
        memo[n] = 1 + max((depth(c) for c in children(n)), default=-1)
    return memo[n]

ordered = sorted(nodes, key=lambda n: (depth(n), str(n)))
consumers = {n: [] for n in nodes}
for n in nodes:
    for c in children(n):
        if c in nodes:
            consumers[c].append(n)

assignment = {}
def live_counts():
    return [
        sum(1 for n in nodes if n in assignment and assignment[n] <= layer and
            (n == expr or any(p not in assignment or assignment[p] > layer
                              for p in consumers[n])))
        for layer in range(4)
    ]

def schedule(i=0):
    if i == len(ordered):
        return max(live_counts(), default=0) <= 8
    n = ordered[i]
    deps = [c for c in children(n) if c in nodes]
    earliest = max((assignment[c] + 1 for c in deps), default=0)
    for layer in range(earliest, 4):
        assignment[n] = layer
        if max(live_counts(), default=0) <= 8 and schedule(i + 1):
            return True
    assignment.pop(n, None)
    return False

if nodes and not schedule():
    raise ValueError("Could not schedule the minimized circuit in four layers")

ops = []
def put(tensor, index, value):
    if value:
        ops.append({"op": "set", "tensor": tensor, "index": index, "value": float(value)})

# Keep raw inputs available in every layer.
for i in range(10):
    put("w0", [i, i], 1)
    for layer in range(1, 4):
        put(f"w{layer}", [i, i], 1)

live, slot = {}, {}
for layer in range(4):
    live[layer] = sorted(
        [n for n in nodes if assignment[n] <= layer and
         (n == expr or any(assignment[p] > layer for p in consumers[n]))],
        key=str
    )
    if len(live[layer]) > 8:
        raise ValueError("More than eight live signals in a layer")
    slot[layer] = {n: 10 + 3 * k for k, n in enumerate(live[layer])}

for layer in range(4):
    # Carry live Boolean signals forward in their two nonnegative rails.
    if layer:
        for n in live[layer]:
            if assignment[n] < layer:
                src, dst = slot[layer - 1][n], slot[layer][n]
                put(f"w{layer}", [dst, src], 1)
                put(f"w{layer}", [dst + 2, src + 2], 1)

    for n in ordered:
        if assignment[n] != layer:
            continue
        dst = slot[layer][n]
        if n.func is sp.Not:
            literals = [(n.args[0], -1)]
            const, threshold = 1, 1
        else:
            literals, const = [], 0
            for arg in n.args:
                neg = arg.func is sp.Not
                v = arg.args[0] if neg else arg
                literals.append((v, -1 if neg else 1))
                if neg:
                    const += 1
            threshold = len(n.args) if n.func is sp.And else 1

        for v, coef in literals:
            if v in xs:
                col = xs.index(v)
                put(f"w{layer}", [dst, col], coef)
                put(f"w{layer}", [dst + 2, col], coef)
            else:
                src = slot[layer - 1][v]
                put(f"w{layer}", [dst, src], coef)
                put(f"w{layer}", [dst, src + 2], -coef)
                put(f"w{layer}", [dst + 2, src], coef)
                put(f"w{layer}", [dst + 2, src + 2], -coef)

        # Decode signal = relu(score-threshold+1) - relu(score-threshold).
        put(f"b{layer}", [dst], const - threshold + 1)
        put(f"b{layer}", [dst + 2], const - threshold)

if expr is sp.true:
    put("bias", [1], 1)
elif expr is sp.false:
    put("bias", [1], -1)
elif expr in xs:
    put("out", [1, xs.index(expr)], 1)
elif is_input_literal(expr):
    put("out", [1, xs.index(expr.args[0])], -1)
    put("bias", [1], 1)
else:
    src = slot[3][expr]
    put("out", [1, src], 1)
    put("out", [1, src + 2], -1)
put("bias", [2], -1)

